mapper.select:
SELECT post_id, user_id, title, subtitle, price, discount_rate, duration,
       max_participants, rating, review_count, like_count,
       city_name, country, lat, lng, created_at AS createdAt, updated_at AS updatedAt
FROM posts


        AND city_name = #{city}


        AND country = #{country}


        AND user_id = #{userId}


ORDER BY post_id DESC

SELECT lang_code AS langCode, tag_name AS tagName
FROM post_tags
WHERE post_id = #{postId}
